import React, { useState, useEffect, useRef } from 'react';
import api from '../../api';

const StockSearch = ({ onSelectStock }) => {
    const [query, setQuery] = useState('');
    const [suggestions, setSuggestions] = useState([]);
    const [loading, setLoading] = useState(false);
    const [showSuggestions, setShowSuggestions] = useState(false);
    const wrapperRef = useRef(null);

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const searchStocks = async (searchQuery) => {
        if (!searchQuery || searchQuery.trim().length < 1) {
            setSuggestions([]);
            setShowSuggestions(false);
            return;
        }

        setLoading(true);
        try {
            const data = await api.searchStocks(searchQuery);
            setSuggestions(data || []);
            setShowSuggestions(true);
        } catch (error) {
            console.error('Error searching stocks:', error);
            setSuggestions([]);
        }
        setLoading(false);
    };

    const handleInputChange = (e) => {
        const value = e.target.value.toUpperCase();
        setQuery(value);
        searchStocks(value);
    };

    const handleSelect = (symbol) => {
        setQuery('');
        setShowSuggestions(false);
        onSelectStock(symbol);
    };

    return (
        <div ref={wrapperRef} style={{ position: 'relative', width: '100%' }}>
            <div style={{ position: 'relative' }}>
                <input
                    type="text"
                    className="soft-input"
                    placeholder="🔍 Search Indian stocks (e.g., RELIANCE, TCS, HDFCBANK, INFY, SBIN)"
                    value={query}
                    onChange={handleInputChange}
                    onFocus={() => query.length >= 1 && setShowSuggestions(true)}
                    style={{
                        width: '100%',
                        padding: '14px 20px',
                        paddingRight: '40px',
                        borderRadius: 'var(--radius-md)',
                        fontSize: '15px',
                        background: '#111927'
                    }}
                />
                {loading && (
                    <div style={{
                        position: 'absolute',
                        right: '15px',
                        top: '50%',
                        transform: 'translateY(-50%)',
                        color: 'var(--accent-primary)'
                    }}>
                        ⏳
                    </div>
                )}
            </div>

            {showSuggestions && suggestions.length > 0 && (
                <div style={{
                    position: 'absolute',
                    top: '100%',
                    left: 0,
                    right: 0,
                    marginTop: '6px',
                    background: 'var(--bg-surface)',
                    border: '1px solid #2e4161',
                    borderRadius: 'var(--radius-md)',
                    maxHeight: '360px',
                    overflowY: 'auto',
                    zIndex: 1000,
                    boxShadow: '0 16px 40px rgba(0,0,0,0.6)'
                }}>
                    {suggestions.map((stock) => (
                        <div
                            key={stock.symbol}
                            onClick={() => handleSelect(stock.symbol)}
                            style={{
                                padding: '12px 18px',
                                cursor: 'pointer',
                                borderBottom: '1px solid var(--border-color)',
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'center',
                                transition: 'background 0.2s'
                            }}
                            onMouseEnter={(e) => e.currentTarget.style.background = 'var(--bg-surface-hover)'}
                            onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
                        >
                            <div>
                                <div style={{ fontWeight: '700', fontSize: '15px', color: 'var(--text-primary)' }}>
                                    {stock.symbol}
                                </div>
                                <div style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>
                                    {stock.name}
                                </div>
                            </div>
                            <div style={{ textAlign: 'right' }}>
                                {stock.price ? (
                                    <div style={{ fontWeight: '700', fontSize: '15px', color: 'var(--accent-emerald)' }}>
                                        ₹{stock.price.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                                    </div>
                                ) : (
                                    <div style={{ color: 'var(--text-muted)', fontSize: '12px' }}>Loading...</div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default StockSearch;
